\version "2.27.2"
% automatically converted by musicxml2ly from 61h-Lyrics-BeamsMelismata.xml
\pointAndClickOff

\header {
  texidoc = "In standard music notation, beaming or slurs normally indicate
    melismata for lyrics (in MusicXML there is no such interdependency). Also
    make sure that notes without an explicit syllable are treated as if they
    were part of a melisma.

    In all measures, the melisma starts on note 1 and ends on note 7; there are
    lyrics on notes 1, 4, and 5, followed by an extender line from note 5 to 7.

    Measure 1 has beams from notes 1 to 3 and 5 to 7.

    In measure 2, there are neither beams nor slurs. ‘start’, ‘continue’, and
    ‘stop’ types are used for <extend>, together with a red color for the
    extender line.

    Measure 3 uses slurs (and no beams) for notes 1 to 3 and 5 to 7.

    Measure 4 uses a single slur (and no beams) from note 1 to 7."
}
\layout {
  \context {
    \Score
    autoBeaming = ##f
  }
}
PartPOneVoiceOne = \relative c'' {
  \once \omit Staff.TimeSignature c8 [ a8 c8 ] a8 c8 [ g8 b8 ] r8 | % 1
  c8 a8 c8 a8 c8 g8 b8 r8 | % 2
  c8 ( a8 c8 ) a8 c8 ( g8 b8 ) r8 | % 3
  c8 ( a8 c8 a8 c8 g8 b8 ) r8 \bar "|."
}

PartPOneVoiceOneLyricsOne = \lyricmode {
  \set ignoreMelismata = ##t
  \set includeGraceNotes = ##t
  Me -- \skip1 \skip1 lis -- ma __ \skip1 \skip1 Me -- \skip1 \skip1 lis -- ma
  \tweak color "#FF0000" __ \skip1 \skip1 Me -- \skip1 \skip1 lis -- ma __
  \skip1 \skip1 Me -- \skip1 \skip1 lis -- ma __ \skip1 \skip1
}


